   123    bool check_success (bool success)
   124    { return this->successful && (success || (err_other_error (), false)); }
   125
   126    template <typename T1, typename T2>
   127    bool check_equal (T1 &&v1, T2 &&v2)
   128    { return check_success (v1 == v2); }
   129
   130    template <typename T1, typename T2>
   131    bool check_assign (T1 &v1, T2 &&v2)
   132    { return check_equal (v1 = v2, v2); }
   133
   134    template <typename T> bool propagate_error (T &&obj)
   135    { return check_success (!hb_deref (obj).in_error ()); }
   136
   137    template <typename T1, typename... Ts> bool propagate_error (T1 &&o1, Ts &&...os)
   138    { return propagate_error (hb_forward<T1> (o1)) &&
   139             propagate_error (hb_forward<Ts> (os)...); }
