   240    void revert (range_t snap)
   241    {
   242      assert (snap.head <= head);
   243      assert (tail <= snap.tail);
   244      head = snap.head;
   245      tail = snap.tail;
   246      discard_stale_objects ();
   247    }
   248
   249    void discard_stale_objects ()
   250    {
   251      while (packed.length > 1 &&
   252             packed.tail ()->head < tail)
   253      {
   254        packed_map.del (packed.tail ());
   255        assert (!packed.tail ()->next);
   256        packed.tail ()->fini ();
   257        packed.pop ();
   258      }
   259      if (packed.length > 1)
   260        assert (packed.tail ()->head == tail);
   261    }
