   263    template <typename T>
   264    void add_link (T &ofs, objidx_t objidx, const void *base = nullptr)
   265    {
   266      static_assert (sizeof (T) == 2 || sizeof (T) == 4, "");
   267
   268      if (!objidx)
   269        return;
   270
   271      assert (current);
   272      assert (current->head <= (const char *) &ofs);
   273
   274      if (!base)
   275        base = current->head;
   276      else
   277        assert (current->head <= (const char *) base);
   278
   279      auto& link = *current->links.push ();
   280      link.is_wide = sizeof (T) == 4;
   281      link.position = (const char *) &ofs - current->head;
   282      link.bias = (const char *) base - current->head;
   283      link.objidx = objidx;
   284    }
   285
   286    void resolve_links ()
   287    {
   288      if (unlikely (in_error ())) return;
   289
   290      assert (!current);
   291      assert (packed.length > 1);
   292
   293      for (const object_t* parent : ++hb_iter (packed))
   294      {
   295        for (const object_t::link_t &link : parent->links)
   296        {
   297          const object_t* child = packed[link.objidx];
   298          assert (link.bias <= (size_t) (parent->tail - parent->head));
   299          unsigned offset = (child->head - parent->head) - link.bias;
   300
   301          if (link.is_wide)
   302          {
   303            auto &off = * ((BEInt<uint32_t, 4> *) (parent->head + link.position));
   304            assert (0 == off);
   305            check_assign (off, offset);
   306          }
   307          else
   308          {
   309            auto &off = * ((BEInt<uint16_t, 2> *) (parent->head + link.position));
   310            assert (0 == off);
   311            check_assign (off, offset);
   312          }
   313        }
   314      }
   315    }
