   333    /* Following two functions exist to allow setting breakpoint on. */
   334    void err_ran_out_of_room () { this->ran_out_of_room = true; }
   335    void err_other_error () { this->successful = false; }
   336
   337    template <typename Type>
   338    Type *allocate_size (unsigned int size)
   339    {
   340      if (unlikely (!this->successful)) return nullptr;
   341
   342      if (this->tail - this->head < ptrdiff_t (size))
   343      {
   344        err_ran_out_of_room ();
   345        this->successful = false;
   346        return nullptr;
   347      }
   348      memset (this->head, 0, size);
   349      char *ret = this->head;
   350      this->head += size;
   351      return reinterpret_cast<Type *> (ret);
   352    }
   353
   354    template <typename Type>
   355    Type *allocate_min ()
   356    {
   357      return this->allocate_size<Type> (Type::min_size);
   358    }
